var i=`0567-chuchvara`;var t=`world-0567`;var o=`UZ`;var l=`central-asia`;var a=4;var g=65;var r={en:`Chuchvara`,ua:`Чучвара`};var s={en:`A traditional dish from Uzbekistan, centered on all-purpose flour, chicken egg, ground beef, yellow onion. A measured home-kitchen version organized by cooking step.`,ua:`Традиційна страва кухні країни Узбекистан. Основні складники: пшеничне борошно універсальне, куряче яйце, яловичий фарш, жовта цибуля. Домашній варіант із кількостями продуктів за етапами приготування.`};var u=[{en:`Mix the dough ingredients, knead until smooth and elastic, then cover and rest for about 18 minutes.`,ua:`Змішайте складники тіста, вимісіть до гладкості й еластичності, накрийте та залиште приблизно на 18 хвилин.`,t:[`mixing`,`kneading`,`resting-dough`],m:18,i:[[`all-purpose-flour`,360,`g`],[`chicken-egg`,1,`pcs`],[`water`,160,`ml`],[`table-salt`,5,`g`]]},{en:`Prepare the filling ingredients: cook or soften any components that require it, let cool, then mix into an even filling.`,ua:`Підготуйте складники начинки: ті, що потребують теплової обробки, приготуйте, охолодіть і змішайте в однорідну начинку.`,t:[`chopping`,`mixing`],m:10,i:[[`ground-beef`,400,`g`],[`yellow-onion`,160,`g`],[`ground-cumin`,4,`g`]]},{en:`Roll the rested dough thinly, cut rounds, place filling in the center and pinch each dumpling tightly closed.`,ua:`Тонко розкачайте відпочиле тісто, виріжте кружальця, викладіть начинку в центр і ретельно заліпіть краї кожного вареника чи пельменя.`,t:[`rolling-out-dough`,`pinching-dumplings`],m:22,i:[]},{en:`Cook dumplings in batches in gently boiling salted water for about 12 minutes, until they float and the filling is cooked through. Lift out with a slotted spoon.`,ua:`Варіть вироби порціями в ледь киплячій підсоленій воді приблизно 12 хвилин, доки вони спливуть і начинка приготується. Вийміть шумівкою.`,t:[`boiling`],m:12,i:[[`water`,1400,`ml`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:3,i:[[`cilantro`,20,`g`],[`plain-yogurt`,140,`g`]]}];var h={slug:i,id:t,country:`UZ`,region:l,servings:4,minutes:65,title:r,text:s,steps:u};export{o as country,h as default,t as id,g as minutes,l as region,a as servings,i as slug,u as steps,s as text,r as title};